-- Synthetic existing-actor fixtures in one rollback. No users/providers/production writes.
begin;
set local lock_timeout='5s';set local statement_timeout='90s';
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999902',true);
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end $$;
create function pg_temp.expect_error(query text,code text,label text) returns void language plpgsql as $$begin begin execute query;exception when others then if sqlstate=code then raise notice 'PASS %',label;return;end if;raise exception 'FAIL % expected % got %: %',label,code,sqlstate,sqlerrm;end;raise exception 'FAIL % did not reject',label;end $$;
-- The known clone-only activity default is changed only inside this rollback for one canonical Task fixture.
alter table public.activity_events alter column organization_id set default '99999999-9999-4999-8999-999999999901'::uuid;
insert into public.backlink_targets(id,organization_id,brand_id,site_name,site_url,domain_authority,estimated_traffic,relevance_score,created_by)
values('99999999-9999-4999-8999-999999997400','99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999973','Synthetic publication research','https://Example.invalid:443/publication/#fragment',null,null,null,'99999999-9999-4999-8999-999999999902'),('99999999-9999-4999-8999-999999997401','99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999973','Duplicate canonical research target','https://example.invalid/publication',0,0,0,'99999999-9999-4999-8999-999999999902');
insert into public.tasks(id,organization_id,project_id,user_id,created_by,title,department_id,due_date,status)
values('99999999-9999-4999-8999-999999997402','99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999902','99999999-9999-4999-8999-999999999902','Synthetic existing governed Marketing Project Task','marketing','2026-10-10','backlog');
do $$declare org uuid:='99999999-9999-4999-8999-999999999901';project uuid:='99999999-9999-4999-8999-999999999974';eng uuid:='99999999-9999-4999-8999-999999999975';service uuid:='99999999-9999-4999-8999-999999997171';input jsonb;review jsonb;saved jsonb;linked jsonb;r jsonb;candidate uuid;target_total bigint;link_input jsonb;ix integer;begin
 select count(*) into target_total from public.backlink_targets where organization_id=org and brand_id='99999999-9999-4999-8999-999999999973';
 r:=public.list_project_marketing_opportunity_candidates(org,project,eng,'canonical_targets','Synthetic publication research');perform pg_temp.check_true(r->>'total'=target_total::text and r->>'matching'='1' and r#>'{items,0,domain_authority}'='null','Canonical target lookup has independent total/matching and unknown manual metrics');
 r:=public.list_project_marketing_opportunity_candidates(org,project,eng,'canonical_targets','Duplicate canonical research target');perform pg_temp.check_true((r#>>'{items,0,estimated_traffic}')::numeric=0 and not (r#>'{items,0}') ? 'notes' and r->>'provider_verified'='false','Zero remains a manual value; selectors omit long notes and provider verification');
 r:=public.list_project_marketing_opportunity_candidates(org,project,eng,'project_tasks','Synthetic existing governed Marketing Project Task');perform pg_temp.check_true(r->>'matching'='1' and r#>>'{items,0,id}'='99999999-9999-4999-8999-999999997402' and r#>>'{items,0,due_date}'='2026-10-10','Commitment selector uses existing scoped Marketing Project Tasks and canonical deadlines');
 perform pg_temp.expect_error(format('select public.list_project_marketing_opportunity_candidates(%L,%L,%L,%L)',org,project,eng,'engagement_work_items'),'22023','Work Items cannot become opportunity Project Tasks');
 input:=jsonb_build_object('command_kind','record_research','target_id','99999999-9999-4999-8999-999999997400','candidate_kind','publication','source_url','https://example.invalid/read-research','observed_on','2026-09-30','notes','Synthetic bounded original source');review:=public.preview_project_marketing_opportunity(org,project,eng,service,input);saved:=public.confirm_project_marketing_opportunity(org,project,eng,service,input,review->>'review_checksum','99999999-9999-4999-8999-999999997450');candidate:=(saved#>>'{candidate,id}')::uuid;
 link_input:=jsonb_build_object('command_kind','link_task','candidate_id',candidate,'observation_id',saved#>>'{observation,id}','task_id','99999999-9999-4999-8999-999999997402');review:=public.preview_project_marketing_opportunity(org,project,eng,service,link_input);linked:=public.confirm_project_marketing_opportunity(org,project,eng,service,link_input,review->>'review_checksum','99999999-9999-4999-8999-999999997451');
 r:=public.list_project_marketing_opportunity_candidates(org,project,eng,'research_candidates','https://example.invalid/publication');perform pg_temp.check_true(r->>'matching'='1' and r#>>'{items,0,observation_count}'='1' and r#>>'{items,0,task_link_count}'='1','Deduped candidate cards keep research observation and commitment counts separate');
 r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'observations');perform pg_temp.check_true(r->>'total'='1' and r#>>'{items,0,id}'=saved#>>'{observation,id}' and r#>>'{items,0,source_url}'=input->>'source_url' and r#>>'{items,0,observed_on}'='2026-09-30','Explicit history retains exact original observation/source/date');
 perform pg_temp.check_true(r#>>'{items,0,current_target_matches}'='true' and r#>>'{items,0,current_service_available}'='true' and r->>'provider_request_made'='false','Current source/service projection remains separate from unverified provider state');
 r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'task_links');perform pg_temp.check_true(r#>>'{items,0,current_task_matches}'='true' and r#>>'{items,0,reference_snapshot,task,due_date}'='2026-10-10','Original canonical Task commitment and current matches are distinct');
 update public.tasks set due_date='2026-10-11' where id='99999999-9999-4999-8999-999999997402';r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'task_links');perform pg_temp.check_true(r#>>'{items,0,current_task_matches}'='false' and r#>>'{items,0,current_task,due_date}'='2026-10-11' and r#>>'{items,0,reference_snapshot,task,due_date}'='2026-10-10','Later Task deadline/revision derives drift without rewriting original commitment');
 update public.backlink_targets set notes='Later canonical source metadata' where id='99999999-9999-4999-8999-999999997400';r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'observations');perform pg_temp.check_true(r#>>'{items,0,current_target_matches}'='false' and r#>>'{items,0,notes}'='Synthetic bounded original source','Later canonical target metadata derives drift while original research remains immutable');
 r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'observations','absent');perform pg_temp.check_true(r->>'total'='1' and r->>'matching'='0' and r->'items'='[]','Research search preserves whole/filtered counts');
 r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'observations','',1,1);perform pg_temp.check_true(r->>'total'='1' and r->'items'='[]' and r->>'has_more'='false','History offset never substitutes a newer record');
 perform pg_temp.expect_error(format('select public.list_project_marketing_opportunity_history(%L,%L,%L,%L,%L)',org,project,eng,'99999999-9999-4999-8999-999999997499','observations'),'42501','Unknown/foreign opportunity cannot broaden history scope');
 perform pg_temp.expect_error(format('select public.list_project_marketing_opportunity_candidates(%L,%L,%L,%L,%L,%L,%L)',org,project,eng,'canonical_targets','',0,51),'22023','Selector limit bound enforced');
 perform pg_temp.expect_error(format('select public.list_project_marketing_opportunity_history(%L,%L,%L,%L,%L,%L,%L,%L)',org,project,eng,candidate,'observations','',-1,25),'22023','History negative offset rejected');
 update public.engagement_services set status='on_hold' where id=service;r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'task_links');perform pg_temp.check_true(r->>'current_service_available'='false' and r->>'total'='1','Withdrawn service preserves original commitment with unavailable current context');
 update public.projects set archived_at=clock_timestamp() where id=project;r:=public.list_project_marketing_opportunity_history(org,project,eng,candidate,'observations');perform pg_temp.check_true(r->>'project_archived'='true' and r->>'total'='1','Archived Team project retains original research history');
 update public.organization_memberships set status='revoked' where organization_id=org and user_id='99999999-9999-4999-8999-999999999902';perform pg_temp.expect_error(format('select public.list_project_marketing_opportunity_history(%L,%L,%L,%L,%L)',org,project,eng,candidate,'observations'),'42501','Every history read rechecks current active Team membership');
 update public.organization_memberships set status='active' where organization_id=org and user_id='99999999-9999-4999-8999-999999999902';update public.projects set archived_at=null where id=project;update public.engagement_services set status='active' where id=service;
 -- Bounded individual snapshots can still exceed a whole paged response; reject rather than truncate source history.
 update public.backlink_targets set notes=repeat('n',20000) where id='99999999-9999-4999-8999-999999997400';
 for ix in 1..7 loop review:=public.preview_project_marketing_opportunity(org,project,eng,service,input);perform public.confirm_project_marketing_opportunity(org,project,eng,service,input,review->>'review_checksum',gen_random_uuid());end loop;
 perform pg_temp.expect_error(format('select public.list_project_marketing_opportunity_history(%L,%L,%L,%L,%L,%L,%L,%L)',org,project,eng,candidate,'observations','',0,25),'22023','Whole history response over131072 rejected without source truncation');
 perform pg_temp.check_true(jsonb_array_length(public.list_project_marketing_opportunity_history(org,project,eng,candidate,'observations','',0,1)->'items')=1,'Explicit smaller page retains complete original bounded observation');
end $$;
set local role authenticated;
select pg_temp.check_true(public.list_project_marketing_opportunity_candidates('99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999975','canonical_targets')->>'provider_request_made'='false','Authenticated bounded canonical selector works without provider calls');
reset role;set local role anon;
select pg_temp.expect_error('select public.list_project_marketing_opportunity_candidates(null,null,null,null)','42501','Anonymous selector denied');
reset role;set local role service_role;
select pg_temp.expect_error('select public.list_project_marketing_opportunity_history(null,null,null,null,null)','42501','Service role cannot bypass current Team history checks');
reset role;rollback;
